from fractions import Fraction
from math import exp, log


def p_adic_valuation(q: Fraction, p: int) -> int:
    """v_p(q): exponent of p in q = a/b (q != 0)."""
    if q == 0:
        raise ValueError("v_p(0) is +infinity")
    a, b = abs(q.numerator), q.denominator
    k = 0
    while a % p == 0:
        a //= p
        k += 1
    while b % p == 0:
        b //= p
        k -= 1
    return k


def p_adic_norm(q: Fraction, p: int) -> float:
    """|q|_p = p^(-v_p(q)), with |0|_p = 0 (the bridge map t -> p^(-t))."""
    if q == 0:
        return 0.0
    return float(p) ** (-p_adic_valuation(q, p))


def capstone_identity(q: Fraction, p: int) -> bool:
    """|q|_p == exp(-v_p(q) * log p) for q != 0."""
    v = p_adic_valuation(q, p)
    return abs(p_adic_norm(q, p) - exp(-v * log(p))) < 1e-9


if __name__ == "__main__":
    from fractions import Fraction
    p = 3
    for q in [Fraction(18), Fraction(5,27), Fraction(7), Fraction(54,5)]:
        print(q, "v=", p_adic_valuation(q,p), "|q|_p=", p_adic_norm(q,p),
              "identity:", capstone_identity(q,p))

from typing import Callable


def iterate(f: Callable[[int], int], n: int, x: int) -> int:
    """Apply f n times to x."""
    for _ in range(n):
        x = f(x)
    return x


def iterated_lipschitz_bound(C: int, n: int, base_val: int) -> int:
    """Certified bound: val(f^[n] x) <= C^n * val(x) (sharp, by induction)."""
    return (C ** n) * base_val


def depth_separation(C: int, layers: int, input_val: int) -> int:
    """An L-layer C-Lipschitz network is C^L-Lipschitz."""
    return iterated_lipschitz_bound(C, layers, input_val)


if __name__ == "__main__":
    f = lambda n: 3*n
    x = 2
    for n in range(6):
        actual = abs(iterate(f, n, x))
        bound = iterated_lipschitz_bound(3, n, abs(x))
        print(f"n={n} actual={actual} bound={bound} ok={actual<=bound}")
    print("4-layer C=3 net constant:", depth_separation(3, 4, abs(x)))

