function pAdicValuation(a, b, p):    # q = a/b
    k := 0
    while a mod p == 0: a := a / p; k := k + 1
    while b mod p == 0: b := b / p; k := k - 1
    return k                          # v_p(q)

function pAdicNorm(q, p):
    if q == 0: return 0
    return p ** (-pAdicValuation(num(q), den(q), p))

